program.run:
const named = thalyx.read("${defined_in}");
thalyx.assert(named.ok, "the file the context named could not be read", named);
const listing = thalyx.list("src");
thalyx.assert(listing.ok, "src could not be listed", listing);
const touched = [];
for (const name of listing.entries.map((entry) => entry.name).sort()) {
  const path = "src/" + name;
  let rounds = 0;
  while (rounds < 8) {
    const source = thalyx.read(path);
    if (!source.ok || !source.text.includes("Keystore")) { break; }
    thalyx.mustWork(thalyx.substitute(path, "Keystore", "KeyVault"), "the substitution in " + path + " did not happen");
    rounds += 1;
  }
  if (rounds > 0) { touched.push(path); }
}
thalyx.assert(touched.includes("${defined_in}"), "the file the context named was not changed", touched);
const seen = thalyx.changed();
const parses = thalyx.validate({ check: "parses" });
return { touched: touched, seen: seen.count, parses: parses.verdict };
